import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import reactor.core.scheduler.Schedulers;

public class ReactorDemo {
    public static void main(String[] args) {
        Flux<String> userStream = Flux.just("Alice", "Bob", "Charlie");

        userStream
            .publishOn(Schedulers.boundedElastic())
            .filter(name -> name.length() > 3)
            .map(String::toUpperCase)
            .flatMap(name -> fetchUserMetadata(name))
            .doOnNext(meta -> System.out.println("Processed: " + meta))
            .blockLast();
    }

    private static Mono<String> fetchUserMetadata(String username) {
        return Mono.just("Metadata for: " + username);
    }
}
